INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Challenge 2016', 'Ski Challenge 2016 is the 12th and last edition of the alpine skiing series Ski Challenge. The game includes the famous alpine downhill tracks of Bormio, Val Gardena, Kitzbühel, Wengen, Val-d’Isère, Garmisch-Partenkirchen, Beaver Creek, Sochi, Schladming and for the first time St. Moritz. The goal for the players is to climb the leaderboards by getting the fastest times. Three day events were held on each track to determine race winners who would win physical prizes. The game marks the end of the series as developers Greentube announced in 2016 that it will be discontinued.' FROM games WHERE igdb_id = 87795 ON CONFLICT (game_id, language_code) DO NOTHING;
