INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chesh', 'Chesh is a two-player digital board game of skill and strategy that looks an awful lot like chess, but plays with a drastically different set of rules. Every game of Chesh starts with different pieces, and each piece has a random movement rule assigned to it. It is up to each player to figure out what everything does, and how to use what''s been given to you in order to win!' FROM games WHERE igdb_id = 15551 ON CONFLICT (game_id, language_code) DO NOTHING;
