INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Untamed: Life of a Cougar', 'Experience the life of a mountain lion in the brutal wild, Fight and maintain your territory, find a mate and raise cubs of your own which will grow into adults as your parenting skills are put to the test. Hunt prey, both big and small as you level up to become an effective and lethal hunter. Fight Predators which pose an ever present danger to you and your cubs, and ultimately come face to face with Man in the form of hunters who will waste no time to put you at the center of an active hunt.' FROM games WHERE igdb_id = 35017 ON CONFLICT (game_id, language_code) DO NOTHING;
