INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Island Tribe', 'You find yourself on a mysterious island in the middle of the ocean inhabited by a forgotten tribe. The islanders lived a carefree and quiet life and everything seemed to be perfect… until one day a great volcano woke up. As the sky spewed lava and ash, the villagers abandoned their homes and ran for their lives! Help the settlers reach the ocean before the great volcano strikes its final blow in Island Tribe, a fun Strategy game!' FROM games WHERE igdb_id = 54117 ON CONFLICT (game_id, language_code) DO NOTHING;
