INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Object: Tracks of Terrorin the world Premium', 'You’ve been hired for your most difficult case – stopping the fearsome figure of a headless knight, bent on terrorizing the city. The De Lupe is said to have stolen his sword in order to unleash his angry spirit – but could there be something more mysterious happening in this beautiful village? Follow the clues that lead to De Lupe disappearance – and discover the dark secret behind the infamous Fire Knight - before it’s too late!' FROM games WHERE igdb_id = 175474 ON CONFLICT (game_id, language_code) DO NOTHING;
