INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Below', 'Below is a story-driven, dungeon-delving RPG card game you can play in your browser. It combines the old-school delights of exploration, looting treasure and subterranean peril with rich storytelling. In Below your life in the world above is as important as your adventures beneath it. Only a fool risks their life for a fistful of gold - but would you do it to protect your family? To drive the invaders from your home? For revenge?' FROM games WHERE igdb_id = 216007 ON CONFLICT (game_id, language_code) DO NOTHING;
